import{_ as a,o as i,c as o,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"projects/music-hud-paper/README.md","filePath":"projects/music-hud-paper/README.md"}'),t={name:"projects/music-hud-paper/README.md"};function l(n,e,s,d,c,u){return i(),o("div",null,[...e[0]||(e[0]=[r('<p><img src="https://cdn.modrinth.com/data/7Rnb6oJr/images/20ba5cbcaf71e2ab70436963776e5f801fea44a7.png" alt="Banner"><img src="https://cdn.modrinth.com/data/7Rnb6oJr/images/b1ab5a9d276489d9f2ef4ecce3fd318e58290553.png" alt="Home View"></p><p><a href="https://deepwiki.com/Etern-34520/MusicHud" target="_blank" rel="noreferrer"><img src="https://deepwiki.com/badge.svg" alt="Ask DeepWiki"></a></p><h4 id="a-gui-based-all-situations-singleplayer-multiplayers-music-mod-plugin-designed-with-zero-modifications-to-game-mechanics" tabindex="-1">A GUI-based, all situations (singleplayer/multiplayers) music mod/plugin designed with zero modifications to game mechanics <a class="header-anchor" href="#a-gui-based-all-situations-singleplayer-multiplayers-music-mod-plugin-designed-with-zero-modifications-to-game-mechanics" aria-label="Permalink to &quot;A GUI-based, all situations (singleplayer/multiplayers) music mod/plugin designed with zero modifications to game mechanics&quot;">​</a></h4><blockquote><p>Due to service scope provided by NetEase, this mod might not work well outside China</p></blockquote><h2 id="related-links" tabindex="-1">Related Links <a class="header-anchor" href="#related-links" aria-label="Permalink to &quot;Related Links&quot;">​</a></h2><p><a href="https://modrinth.com/mod/music-hud" target="_blank" rel="noreferrer">ModRinth</a></p><p><a href="https://www.curseforge.com/minecraft/mc-mods/music-hud" target="_blank" rel="noreferrer">CurseForge</a></p><p><a href="https://github.com/Shiroiame-Kusu/MusicHud-Bukkit" target="_blank" rel="noreferrer">Third-party Bukkit plugin 1</a> (1.0.5 stable -)</p><p><a href="https://github.com/MOPELotus/MusicHud-Paper" target="_blank" rel="noreferrer">Third-party Bukkit plugin 2</a> (1.1.4 hotfix +, now partly merged into main repository)</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>ModernUI (only client, using mVUS fork on 1.21.9-11, <a href="https://github.com/Chino081/ModernUI-MC/releases/tag/26.2" target="_blank" rel="noreferrer">this fork</a> on 26.2)</li><li>Forge Config API Port (only fabric)</li><li><s>Architectury API</s> (Mod edition, 1.2.0 and below)</li></ul><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>With graceful GUI, providing an in-game operation interface and a easily configurable HUD.</li><li>Can read NetEase Cloud Music account playlists for convenient song requests.</li><li>The server does not retain user data; it is only temporarily stored during login.</li><li>Streamed playback with no redundant client-side caching.</li><li>Staggered lyrics auto scroll inspired by Apple Music</li><li>HUD dynamic fluid background</li><li>Windows SMTC / Linux MPRIS (have not fully tested yet) support</li></ul><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><ul><li>Search for musics, playlists, albums and artists.</li><li>Log in to NetEase Cloud Music account via QR code or SMS code to explore subscribed playlists, albums and artists.</li><li>Connected mode: Synchronized server-wide play queue.</li><li>Isolated mode: Do all works on client, enjoy music yourself.</li><li>Configure idle playback sources for automatic random song switching when music player is idle.</li><li>Display lyrics, requesting player (or avatar) in the HUD and user interface.</li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><ul><li>Currently specially supports to mute Reactive Music when MusicHUD is playing</li></ul><h2 id="to-do-list" tabindex="-1">TO-DO List <a class="header-anchor" href="#to-do-list" aria-label="Permalink to &quot;TO-DO List&quot;">​</a></h2><ul><li>Customizable HUD layout [target 1.3.0/1.4.0]</li><li>More music platform support (QQ Music, Kugou Music) [target 2.0.0]</li></ul><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h3><p>First of all, place the prerequisite mods and the MusicHud jar file into the mods folder.</p><h4 id="single-player-or-lan-multi-player-host" tabindex="-1">Single-player or LAN Multi-player Host <a class="header-anchor" href="#single-player-or-lan-multi-player-host" aria-label="Permalink to &quot;Single-player or LAN Multi-player Host&quot;">​</a></h4><p>All you need is to configure or deploy an API server.</p><h4 id="multiplayer-join-server-or-lan-multi-player" tabindex="-1">Multiplayer (join Server or LAN Multi-player) <a class="header-anchor" href="#multiplayer-join-server-or-lan-multi-player" aria-label="Permalink to &quot;Multiplayer (join Server or LAN Multi-player)&quot;">​</a></h4><h5 id="connected-mode" tabindex="-1">Connected mode <a class="header-anchor" href="#connected-mode" aria-label="Permalink to &quot;Connected mode&quot;">​</a></h5><p>You don&#39;t need to configure or deploy an API server, but the server or LAN multiplayer host needs to configure or deploy MusicHUD and API server.</p><h5 id="isolated-mode" tabindex="-1">Isolated mode <a class="header-anchor" href="#isolated-mode" aria-label="Permalink to &quot;Isolated mode&quot;">​</a></h5><p>All you need is to configure or deploy an API server.</p><h3 id="server" tabindex="-1">Server <a class="header-anchor" href="#server" aria-label="Permalink to &quot;Server&quot;">​</a></h3><p>All you need is to configure or deploy an API server.</p><h3 id="how-to-deploy-an-api-server" tabindex="-1">How to Deploy an API Server <a class="header-anchor" href="#how-to-deploy-an-api-server" aria-label="Permalink to &quot;How to Deploy an API Server&quot;">​</a></h3><p>There are 2 methods to deploy.</p><h4 id="deploy-bound-with-mod-recommend-for-client" tabindex="-1">Deploy bound with mod (recommend for client) <a class="header-anchor" href="#deploy-bound-with-mod-recommend-for-client" aria-label="Permalink to &quot;Deploy bound with mod (recommend for client)&quot;">​</a></h4><blockquote><p>This method allows MusicHUD to manage lifecycle of api server.</p><p>Due to some limitations, API Server may not be auto-closed when game exit abnormal (e.g., due to a crash)</p></blockquote><h5 id="auto-deploy" tabindex="-1">Auto Deploy <a class="header-anchor" href="#auto-deploy" aria-label="Permalink to &quot;Auto Deploy&quot;">​</a></h5><p>You can find &quot;Download API...&quot; button in setting page, which will open a download guide, and download NetEase Cloud Music Enhanced from <a href="https://github.com/MOPELotus/api-enhanced" target="_blank" rel="noreferrer">a trusted repository</a> which automatically releases artifact powered by GitHub Actions to bypass login restrictions of accessing artifacts from GitHub Actions, with optional GH Proxy speedup</p><h5 id="manual-deploy" tabindex="-1">Manual Deploy <a class="header-anchor" href="#manual-deploy" aria-label="Permalink to &quot;Manual Deploy&quot;">​</a></h5><ol><li><strong>Login to GitHub (Important, otherwise can NOT download artifacts)</strong> and go to <a href="https://github.com/NeteaseCloudMusicApiEnhanced/api-enhanced/actions/workflows/build-dev.yml" target="_blank" rel="noreferrer">https://github.com/NeteaseCloudMusicApiEnhanced/api-enhanced/actions/workflows/build-dev.yml</a></li><li>Click latest action runs in type &quot;Build Artifacts&quot; and download platform binary artifacts matches to your pc/server platform</li><li>Uncompress the binary executable file from ZIP file to ... <ul><li>Mod edition: <code>{corepath}/music-hud/</code> and rename it to <code>api</code> (<code>api.exe</code> on Windows)</li><li>Plugin edition: <code>{corepath}/plugins/MusicHud/</code> and rename it to <code>api</code> (<code>api.exe</code> on Windows)</li><li>Or place it anywhere and modify config in game or option <code>serverApiBinaryExecutablePath</code> (absolute or relative path) in config file <code>/config/music_hud-common.toml</code>.</li></ul></li></ol><h4 id="deploy-separately-recommend-for-server" tabindex="-1">Deploy separately (recommend for server) <a class="header-anchor" href="#deploy-separately-recommend-for-server" aria-label="Permalink to &quot;Deploy separately (recommend for server)&quot;">​</a></h4><ol><li>Deploy NetEase Cloud Music API Enhanced (<a href="https://github.com/neteasecloudmusicapienhanced/api-enhanced" target="_blank" rel="noreferrer">https://github.com/neteasecloudmusicapienhanced/api-enhanced</a>).</li><li>If not using the default port (3000) of NCM API Enhanced or deploying on another server, modify the <code>serverApiBaseUrl</code> property in the config file <code>/config/music_hud-server.toml</code>.</li></ol><hr><h2 id="cn-version-description" tabindex="-1">CN version description <a class="header-anchor" href="#cn-version-description" aria-label="Permalink to &quot;CN version description&quot;">​</a></h2><h4 id="图形化的全场景-单人-多人游戏-音乐模组-插件-设计上不修改任何游戏机制" tabindex="-1">图形化的全场景（单人/多人游戏）音乐模组/插件，设计上不修改任何游戏机制 <a class="header-anchor" href="#图形化的全场景-单人-多人游戏-音乐模组-插件-设计上不修改任何游戏机制" aria-label="Permalink to &quot;图形化的全场景（单人/多人游戏）音乐模组/插件，设计上不修改任何游戏机制&quot;">​</a></h4><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><p><a href="https://www.mcmod.cn/class/23688.html" target="_blank" rel="noreferrer">MC 百科</a></p><p><a href="https://github.com/Shiroiame-Kusu/MusicHud-Bukkit" target="_blank" rel="noreferrer">第三方 Bukkit 插件实现 1</a> (1.0.5 stable -)</p><p><a href="https://github.com/MOPELotus/MusicHud-Paper" target="_blank" rel="noreferrer">第三方 Bukkit 插件实现 2</a> (1.1.4 hotfix +，目前已部分合并至主仓库)</p><h2 id="前置依赖" tabindex="-1">前置依赖 <a class="header-anchor" href="#前置依赖" aria-label="Permalink to &quot;前置依赖&quot;">​</a></h2><ul><li>ModernUI （仅客户端，在 1.21.9 上使用 mVUS 分支，在 26.2 上使用<a href="https://github.com/Chino081/ModernUI-MC/releases/tag/26.2" target="_blank" rel="noreferrer">该分支</a>）</li><li>Forge Config API Port （仅 Fabric）</li><li><s>Architectury API</s> （非插件版，1.2.0 以及更低版本）</li></ul><h2 id="特点" tabindex="-1">特点 <a class="header-anchor" href="#特点" aria-label="Permalink to &quot;特点&quot;">​</a></h2><ul><li>具有优雅的 GUI，提供游戏内操作界面，以及易配置的 HUD</li><li>可读取网易云账户歌单，方便点歌</li><li>服务端不保留用户数据，仅在登录时暂存</li><li>流式播放，无赘余的客户端缓存</li><li>受 Apple Music 启发的歌词交错滚动与逐字歌词</li><li>HUD 动态流体背景</li><li>Windows SMTC / Linux MPRIS（尚未充分测试） 支持</li></ul><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h2><ul><li>搜索音乐、歌单、专辑和歌手</li><li>通过二维码或短信验证码登录网易云账户，查看收藏的歌单、专辑和歌手</li><li>连接模式：全服同步播放队列</li><li>隔离模式：在客户端上独立享受音乐</li><li>配置空闲播放源，播放器空闲时随机切歌</li><li>在 HUD 和用户界面中展示歌词，点歌玩家（或头像）</li></ul><h2 id="兼容" tabindex="-1">兼容 <a class="header-anchor" href="#兼容" aria-label="Permalink to &quot;兼容&quot;">​</a></h2><ul><li>目前特殊支持在 MusicHUD 播放时静音 Reactive Music</li></ul><h2 id="大饼-待办清单" tabindex="-1"><s>大饼</s> 待办清单 <a class="header-anchor" href="#大饼-待办清单" aria-label="Permalink to &quot;~~大饼~~ 待办清单&quot;">​</a></h2><ul><li>可自定义的 HUD 布局 [目标 1.3.0/1.4.0]</li><li>更多音乐平台支持(QQ音乐, 酷狗音乐) [目标 2.0.0]</li></ul><h2 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to &quot;使用&quot;">​</a></h2><h3 id="客户端" tabindex="-1">客户端 <a class="header-anchor" href="#客户端" aria-label="Permalink to &quot;客户端&quot;">​</a></h3><p>首先在 mods 文件夹中放入前置 mod 和 MusicHUD 的 jar 文件</p><h4 id="单人模式-或-局域网联机主机" tabindex="-1">单人模式 或 局域网联机主机 <a class="header-anchor" href="#单人模式-或-局域网联机主机" aria-label="Permalink to &quot;单人模式 或 局域网联机主机&quot;">​</a></h4><p>只需要配置/部署 API 服务器</p><h4 id="加入服务器-或-加入局域网世界" tabindex="-1">加入服务器 或 加入局域网世界 <a class="header-anchor" href="#加入服务器-或-加入局域网世界" aria-label="Permalink to &quot;加入服务器 或 加入局域网世界&quot;">​</a></h4><h5 id="连接模式" tabindex="-1">连接模式 <a class="header-anchor" href="#连接模式" aria-label="Permalink to &quot;连接模式&quot;">​</a></h5><p>不需要配置/部署 API 服务器</p><p>但是需要服务器/局域网主机配置/部署 MusicHUD 和 API 服务器</p><h5 id="隔离模式" tabindex="-1">隔离模式 <a class="header-anchor" href="#隔离模式" aria-label="Permalink to &quot;隔离模式&quot;">​</a></h5><p>只需要配置/部署 API 服务器</p><h3 id="服务端" tabindex="-1">服务端 <a class="header-anchor" href="#服务端" aria-label="Permalink to &quot;服务端&quot;">​</a></h3><p>只需要部署 API 服务器</p><h3 id="如何部署-api-服务器" tabindex="-1">如何部署 API 服务器 <a class="header-anchor" href="#如何部署-api-服务器" aria-label="Permalink to &quot;如何部署 API 服务器&quot;">​</a></h3><p>两种方法</p><h4 id="绑定在-mod-中-推荐客户端使用" tabindex="-1">绑定在 mod 中（推荐客户端使用） <a class="header-anchor" href="#绑定在-mod-中-推荐客户端使用" aria-label="Permalink to &quot;绑定在 mod 中（推荐客户端使用）&quot;">​</a></h4><blockquote><p>这个方法会让 MusicHUD 管理 API 服务器生命周期</p><p>由于一些限制，在游戏非正常退出时（如崩溃）无法自动结束进程</p></blockquote><h5 id="自动部署-客户端-1-2-15" tabindex="-1">自动部署（客户端，1.2.15+） <a class="header-anchor" href="#自动部署-客户端-1-2-15" aria-label="Permalink to &quot;自动部署（客户端，1.2.15+）&quot;">​</a></h5><p>在设置页面中的 API 状态一栏中可找到“下载 API...”按钮，可打开一个下载指引，会从一个通过 GitHub Actions 自动发布 release 的<a href="https://github.com/MOPELotus/api-enhanced" target="_blank" rel="noreferrer">可信的分支仓库</a>下载 NetEase Cloud Music Enhanced 以绕过访问 GitHub Actions 工件的登录限制，可选使用 GH Proxy 加速下载</p><h5 id="手动部署" tabindex="-1">手动部署 <a class="header-anchor" href="#手动部署" aria-label="Permalink to &quot;手动部署&quot;">​</a></h5><ol><li><strong>登录到 GitHub (重要，否则无法下载工件)</strong> 并跳转到 <a href="https://github.com/NeteaseCloudMusicApiEnhanced/api-enhanced/actions/workflows/build-dev.yml" target="_blank" rel="noreferrer">https://github.com/NeteaseCloudMusicApiEnhanced/api-enhanced/actions/workflows/build-dev.yml</a></li><li>在 actions 类型中选择 &quot;Build Artifacts&quot; 并进入最新的构建中根据你的平台下载对应的二进制构建产物</li><li>解压下载得到的压缩包并将其中的二进制可执行文件放置到... <ul><li>mod 版：{核心目录}/music-hud/ 并重命名为 <code>api</code> (对于 Windows 为 <code>api.exe</code>)</li><li>插件版: {核心目录}/plugins/MusicHud/api(.exe)</li><li>或者放在任意处并在游戏内或配置文件<code>/config/music_hud-common.toml</code>中修改选项 <code>serverApiBinaryExecutablePath</code> 对应(绝对/相对)目录</li></ul></li></ol><h4 id="独立部署-推荐服务端使用" tabindex="-1">独立部署（推荐服务端使用） <a class="header-anchor" href="#独立部署-推荐服务端使用" aria-label="Permalink to &quot;独立部署（推荐服务端使用）&quot;">​</a></h4><ol><li>部署 Netease Cloud Music API Enhanced (<a href="https://github.com/neteasecloudmusicapienhanced/api-enhanced" target="_blank" rel="noreferrer">https://github.com/neteasecloudmusicapienhanced/api-enhanced</a>)</li><li>如果不使用 NCM API Enhanced 的默认端口 ( 3000 ) 或在其他服务器上部署，需要修改配置文件<code>/config/music_hud-server.toml</code>的 <code>serverApiBaseUrl</code> 属性</li></ol>',81)])])}const m=a(t,[["render",l]]);export{p as __pageData,m as default};
